import re

def parse_endpoint(addr_str):
    # Bug: allows port numbers > 65535 (e.g. 99999) and unanchored substrings
    pattern = r"([a-zA-Z0-9.-]+):(\d+)"
    m = re.search(pattern, addr_str)
    if m:
        return m.group(1), int(m.group(2))
    return None

